/**
 * Strict access-code gate (middleware).
 * Bot Number A stays silent unless an authorized user sends their exact ACCESS_CODE.
 */
const { AccessUsers } = require('../../models');
const antiBan = require('../../services/antiBan');

/**
 * @param {{ phone: string, body: string }} input
 * @returns {{
 *   action: 'silent' | 'dispatch_form',
 *   reason: string,
 *   user?: object,
 *   canonicalPhone?: string
 * }}
 */
function evaluateAccessGate({ phone, body }) {
  if (!antiBan.isWithinWorkingHours()) {
    return { action: 'silent', reason: 'outside_hours' };
  }

  const text = String(body || '').trim();
  if (!text) {
    return { action: 'silent', reason: 'empty_body' };
  }

  const user = AccessUsers.findByPhone(phone);
  if (!user || !user.is_active) {
    return { action: 'silent', reason: 'unauthorized' };
  }

  const status = AccessUsers.displayStatus(user);
  const canonicalPhone = user.phone || phone;

  if (status === 'waiting_code') {
    const unlock = AccessUsers.tryUnlock(phone, text);
    if (!unlock.ok) {
      return { action: 'silent', reason: unlock.reason || 'wrong_code', user };
    }
    return {
      action: 'dispatch_form',
      reason: unlock.reason || 'unlocked',
      user: unlock.user || user,
      canonicalPhone,
    };
  }

  // Active (or other): silence until form submit opens the two-way bridge
  return {
    action: 'silent',
    reason: status === 'active' ? 'already_active' : `status_${status}`,
    user,
    canonicalPhone,
  };
}

module.exports = { evaluateAccessGate };
